import React, { useState, useEffect } from "react";
import "./AttendanceDetailsPage.css"; // We'll add CSS next

export default function AttendanceDetailsPage() {
  const [employee, setEmployee] = useState(null);
  const [attendance, setAttendance] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Get data passed from AdminDashboard via localStorage (simple navigation state)
    const empData = localStorage.getItem("viewAttendanceEmployee");
    if (!empData) {
      window.location.href = "/admin-dashboard"; // Safety redirect
      return;
    }

    const emp = JSON.parse(empData);
    setEmployee(emp);

    // Fetch attendance
    fetch(`http://localhost:5000/api/attendance/${emp.userId}`)
      .then(res => {
        if (!res.ok) throw new Error("Failed to load attendance");
        return res.json();
      })
      .then(data => {
        // Sort by date descending (latest first)
        const sorted = data.sort((a, b) => new Date(b.date) - new Date(a.date));
        setAttendance(sorted);
      })
      .catch(err => {
        console.error(err);
        setAttendance([]);
      })
      .finally(() => setLoading(false));

    // Cleanup when leaving page
    return () => localStorage.removeItem("viewAttendanceEmployee");
  }, []);

  const goBack = () => {
    window.history.back(); // Or window.location.href = "/admin-dashboard"
  };

  return (
    <div className="attendance-details-page">
      <div className="page-header">
        <button className="back-btn" onClick={goBack}>
          ← Back to Employees
        </button>
        <h1>Attendance Details</h1>
      </div>

      {employee && (
        <div className="employee-info">
          <h2>{employee.name}</h2>
          <p>
            <strong>ID:</strong> {employee.userId} | 
            <strong> Designation:</strong> {employee.designation} | 
            <strong> Branch:</strong> {employee.branch}
          </p>
        </div>
      )}

      <div className="attendance-records">
        {loading ? (
          <p className="loading">Loading attendance records...</p>
        ) : attendance.length === 0 ? (
          <p className="no-records">No attendance records found for this employee.</p>
        ) : (
          <table className="attendance-table">
            <thead>
              <tr>
                <th>Date</th>
                <th>Check In</th>
                <th>Check Out</th>
                <th>Hours Worked</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {attendance.map((record, index) => {
                const hours = parseFloat(record.hours || 0);
                const status = hours >= 9 ? "Full Day" : hours >= 4.5 ? "Half Day" : "Short";
                const statusClass = status === "Full Day" ? "status-full" :
                                   status === "Half Day" ? "status-half" : "status-short";

                return (
                  <tr key={index}>
                    <td>{record.date}</td>
                    <td>{record.checkIn || "--"}</td>
                    <td>{record.checkOut || "--"}</td>
                    <td>{hours.toFixed(2)}</td>
                    <td>
                      <span className={`status-badge ${statusClass}`}>
                        {status}
                      </span>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}
